package org.harbourcu.common;

import java.lang.reflect.*;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping;

/** Local schema/route catalogue generated from actual controller mappings; absent in production. */
@RestController @Profile("!prod")
public class ApiDocumentationController {
 private final RequestMappingHandlerMapping mappings;
 public ApiDocumentationController(@org.springframework.beans.factory.annotation.Qualifier("requestMappingHandlerMapping") RequestMappingHandlerMapping mappings){this.mappings=mappings;}
 @GetMapping("/api/docs") public ResponseEntity<?> document(){Map<String,Object> paths=new TreeMap<>();mappings.getHandlerMethods().forEach((mapping,handler)->{if(!handler.getBeanType().getPackageName().startsWith("org.harbourcu"))return;for(String path:mapping.getPatternValues()){if(!path.startsWith("/api/v1/"))continue;Map<String,Object> operations=(Map<String,Object>)paths.computeIfAbsent(path,p->new TreeMap<>());for(var verb:mapping.getMethodsCondition().getMethods()){
  var op=new LinkedHashMap<String,Object>();op.put("operationId",handler.getBeanType().getSimpleName()+"_"+handler.getMethod().getName()+"_"+verb.name());op.put("tags",List.of(handler.getBeanType().getSimpleName().replace("Controller","")));boolean publicRoute=path.startsWith("/api/v1/auth/")||path.endsWith("/webhook")||path.endsWith("/health")||path.endsWith("/organization/branding");op.put("security",publicRoute?List.of():List.of(Map.of("session",List.of())));
  var parameters=new ArrayList<Object>();for(var parameter:handler.getMethod().getParameters()){var query=parameter.getAnnotation(RequestParam.class);var variable=parameter.getAnnotation(PathVariable.class);var header=parameter.getAnnotation(RequestHeader.class);var body=parameter.getAnnotation(RequestBody.class);
   if(body!=null)op.put("requestBody",Map.of("required",body.required(),"content",Map.of("application/json",Map.of("schema",schema(parameter.getParameterizedType(),new HashSet<>())))));
   if(query!=null||variable!=null||header!=null){String where=variable!=null?"path":header!=null?"header":"query";String name=variable!=null?(variable.value().isEmpty()?variable.name():variable.value()):header!=null?(header.value().isEmpty()?header.name():header.value()):(query.value().isEmpty()?query.name():query.value());if(name.isEmpty())name=parameter.getName();parameters.add(Map.of("name",name,"in",where,"required",variable!=null||(header!=null?header.required():query.required()&&query.defaultValue().equals(org.springframework.web.bind.annotation.ValueConstants.DEFAULT_NONE)),"schema",schema(parameter.getParameterizedType(),new HashSet<>())));}
  }if(!parameters.isEmpty())op.put("parameters",parameters);op.put("responses",Map.of("200",Map.of("description","Successful response; money values are decimal strings."),"204",Map.of("description","Action completed without a body."),"400",Map.of("description","Invalid input; standard ApiError."),"401",Map.of("description","Authentication required."),"403",Map.of("description","Current permission, ownership or CSRF/origin denied."),"409",Map.of("description","Stale financial source, duplicate reference or conflicting state.")));operations.put(verb.name().toLowerCase(Locale.ROOT),op);
 }}});return ResponseEntity.ok().header("Cache-Control","no-store").body(Map.of("openapi","3.0.3","info",Map.of("title","Credit Union Management API","version","1.0","description","Generated local route and request-schema catalogue. All authenticated mutations require the current X-CSRF-Token and allowed origin. Financial POST actions accept Idempotency-Key; identical successful retries return the original UUID acknowledgement. Use the workflow guide for permission and approval rules."),"servers",List.of(Map.of("url","/")),"paths",paths,"components",Map.of("securitySchemes",Map.of("session",Map.of("type","apiKey","in","cookie","name","cu_access")),"schemas",Map.of("ApiError",schema(ApiError.class,new HashSet<>())))));}
 private Map<String,Object> schema(Type type,Set<Type> seen){if(type instanceof ParameterizedType p){if(p.getRawType() instanceof Class<?> c&&Collection.class.isAssignableFrom(c))return Map.of("type","array","items",schema(p.getActualTypeArguments()[0],seen));return Map.of("type","object");}if(!(type instanceof Class<?> c))return Map.of("type","object");if(c==UUID.class)return Map.of("type","string","format","uuid");if(c==java.time.LocalDate.class)return Map.of("type","string","format","date");if(c==java.time.Instant.class||c==java.time.OffsetDateTime.class)return Map.of("type","string","format","date-time");if(c==boolean.class||c==Boolean.class)return Map.of("type","boolean");if(c==String.class||c==java.math.BigDecimal.class)return Map.of("type","string");if(c.isPrimitive()||Number.class.isAssignableFrom(c))return Map.of("type","integer");if(c.isEnum())return Map.of("type","string","enum",Arrays.stream(c.getEnumConstants()).map(Object::toString).toList());if(c.isRecord()&&seen.add(c)){Map<String,Object> properties=new TreeMap<>();for(var part:c.getRecordComponents())properties.put(part.getName(),schema(part.getGenericType(),new HashSet<>(seen)));return Map.of("type","object","properties",properties);}return Map.of("type","object");}
}
